const $=id=>document.getElementById(id);
const defaults={version:1,name:'My everyday voice',tone:'Warm',style:'Professional',guidelines:'Be approachable, get to the point, and keep it human.',avoid:[],signature:'Best,',sender:''};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let voice=read('replyStudio.voice',defaults),responses=read('replyStudio.responses',[]),activeId=null;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Storage is full or unavailable. Export your work to keep it.');return false}}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500)}
function showPage(page){document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==page);document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.page===page));const titles={builder:['Good replies. <em>Your voice.</em>','Turn the email in front of you into a response that sounds like you.','Reply builder'],library:['Good words, <em>worth keeping.</em>','Your response library. Find a starting point for your next conversation.','Saved responses'],voice:['Sound like <em>yourself.</em>','Define how you communicate. Keep every reply feeling consistent.','My voice']};$('pageTitle').innerHTML=titles[page][0];$('pageDesc').textContent=titles[page][1];$('breadcrumb').innerHTML='Workspace <span>/</span> <b>'+titles[page][2]+'</b>';if(page==='library')renderLibrary();if(page==='voice')syncVoice();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>showPage(el.dataset.page));
function updateCounts(){$('incomingCount').textContent=$('incoming').value.length+' characters';const words=$('reply').value.trim().split(/\s+/).filter(Boolean).length;$('wordCount').textContent=words+' words';$('emptyReply').hidden=!!$('reply').value;$('reply').hidden=!$('reply').value;$('savedCount').textContent=responses.length}
['incoming','reply'].forEach(id=>$(id).addEventListener('input',()=>{updateCounts();saveDraft()}));['subject','intent','length','preset'].forEach(id=>$(id).addEventListener('input',saveDraft));
function saveDraft(){persist('replyStudio.draft',{subject:$('subject').value,incoming:$('incoming').value,intent:$('intent').value,reply:$('reply').value,length:$('length').value,preset:$('preset').value})}
const draft=read('replyStudio.draft',{});for(const key of ['subject','incoming','intent','reply','length','preset'])if(draft[key])$(key).value=draft[key];
$('example').onclick=()=>{$('subject').value='Next steps for the website project';$('incoming').value='Hi Alex,\n\nThanks for walking us through the proposal yesterday. We really liked the direction and would love to move forward.\n\nCould you send over a revised timeline and let us know if you’re available for a quick kickoff call next week? Tuesday or Thursday afternoon would work well for our team.\n\nLooking forward to working together!\n\nBest,\nJamie';$('intent').value='Excited to work together. I’ll send the revised timeline by Friday. Thursday afternoon works for a kickoff call. Ask what time suits them.';updateCounts();saveDraft();toast('Example loaded. Add your own details or build a reply.')};
document.querySelectorAll('[data-intent]').forEach(el=>el.onclick=()=>{$('intent').value=el.dataset.intent;saveDraft();$('intent').focus()});
function sentence(text){text=text.trim();if(!text)return '';return text.charAt(0).toUpperCase()+text.slice(1)+( /[.!?]$/.test(text)?'':'.')}
$('generate').onclick=()=>{if(!$('incoming').value.trim()){toast('Paste the email you received first.');$('incoming').focus();return}if(!$('intent').value.trim()){toast('Add what you’d like to say so the reply reflects your intent.');$('intent').focus();return}let tone=voice.tone,style=voice.style;if($('preset').value==='formal'){tone='Neutral';style='Formal'}if($('preset').value==='casual'){tone='Warm';style='Casual'}const mail=$('incoming').value;let name='';const sign=mail.match(/(?:Best|Thanks|Regards|Cheers|Sincerely|Warm regards)[,!]?\s*\n+\s*([A-Za-z][A-Za-z '-]{0,30})(?:\n|$)/i);if(sign)name=sign[1].trim();const greeting=style==='Formal'?'Hello'+(name?' '+name:'')+',':style==='Casual'?'Hey'+(name?' '+name:'')+',':'Hi'+(name?' '+name:'')+',';const intent=$('intent').value.trim();let body=intent;if(intent==='Thank them and acknowledge their email.')body='Thank you for your email. I appreciate you taking the time to reach out.';else if(intent==='Politely decline their request.')body='Thank you for thinking of me. Unfortunately, I’m unable to take this on at the moment. I appreciate your understanding.';else if(intent==='Ask for more information before deciding.')body='Thank you for reaching out. Could you share a little more detail about what you have in mind? That will help me consider the next steps.';else if(intent==='Suggest a meeting to discuss next steps.')body='Thank you for your email. It would be helpful to find a time to discuss the next steps together. Could you send over a few times that work for you?';else body=sentence(body).replace(/\bAsk what time suits them\./i,'What time would work best for you?').replace(/\bAsk (?:them )?if (.+?)\./gi,'Could you let me know if $1?').replace(/\bExcited to work together\./i,'I’m excited to work together.');let opening=tone==='Warm'?'Thanks for getting in touch.':tone==='Direct'?'':'Thank you for your email.';if(/^(Thank|I’m excited)/i.test(body))opening='';let closing=$('length').value==='detailed'?(tone==='Warm'?'I appreciate your time and look forward to hearing from you.':'Please let me know if you have any questions.') : '';if($('length').value==='short')opening='';if(/concise|brief|short/i.test(voice.guidelines)&&$('length').value!=='detailed')closing='';let result=[greeting,opening,body,closing,[voice.signature,voice.sender].filter(Boolean).join('\n')].filter(Boolean).join('\n\n');for(const phrase of voice.avoid||[]){if(!phrase.trim())continue;result=result.replace(new RegExp(phrase.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),'').replace(/ {2,}/g,' ')}$('reply').value=result;$('voiceLabel').textContent=$('preset').selectedOptions[0].text;activeId=null;updateCounts();saveDraft();toast('Draft built from your key points. Review and edit before sending.')};
$('newReply').onclick=()=>{if(($('incoming').value||$('reply').value)&&!confirm('Start a new reply? Save or copy your current response first.'))return;['subject','incoming','intent','reply'].forEach(id=>$(id).value='');activeId=null;saveDraft();updateCounts();showPage('builder');$('incoming').focus()};
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. Select the response and copy it manually.')}}$('copy').onclick=()=>{if(!$('reply').value)return toast('Build a reply first.');copy($('reply').value)};
$('save').onclick=()=>{if(!$('reply').value.trim())return toast('Build or write a response first.');$('responseName').value=$('subject').value||'';$('saveDialog').showModal()};
$('confirmSave').onclick=e=>{if(!$('responseName').value.trim())return;const item={id:activeId||crypto.randomUUID(),title:$('responseName').value.trim(),subject:$('subject').value,incoming:$('incoming').value,intent:$('intent').value,reply:$('reply').value,date:new Date().toISOString()};const next=responses.filter(x=>x.id!==item.id);next.unshift(item);if(persist('replyStudio.responses',next)){responses=next;activeId=item.id;updateCounts();toast('Response saved to your library.')}else e.preventDefault()};
function renderLibrary(){const list=$('responseList');list.replaceChildren();const query=$('search').value.toLowerCase();const matches=responses.filter(x=>(x.title+' '+x.reply).toLowerCase().includes(query));if(!matches.length){const el=document.createElement('div');el.className='library-empty';el.textContent=responses.length?'No responses match your search.':'Your library starts with a good reply. Save your first response from the builder.';list.append(el);return}matches.forEach(item=>{const card=document.createElement('article');card.className='card saved-card';const h=document.createElement('h3');h.textContent=item.title;const date=document.createElement('small');date.textContent='Saved '+new Date(item.date).toLocaleDateString();const body=document.createElement('p');body.textContent=item.reply;const actions=document.createElement('div');actions.className='saved-actions';[['Copy',()=>copy(item.reply)],['Open in builder',()=>{for(const key of ['subject','incoming','intent','reply'])$(key).value=item[key]||'';activeId=item.id;updateCounts();saveDraft();showPage('builder')}],['Delete',()=>{if(confirm('Delete this saved response?')){const next=responses.filter(x=>x.id!==item.id);if(persist('replyStudio.responses',next)){responses=next;updateCounts();renderLibrary();toast('Response deleted.')}}}]].forEach(([title,fn])=>{const b=document.createElement('button');b.className='outline';b.textContent=title;b.onclick=fn;actions.append(b)});card.append(h,date,body,actions);list.append(card)})}$('search').oninput=renderLibrary;
function syncVoice(){for(const [id,key] of [['voiceName','name'],['warmth','tone'],['formality','style'],['guidelines','guidelines'],['signature','signature'],['sender','sender']])$(id).value=voice[key]||'';$('avoid').value=(voice.avoid||[]).join(', ');$('configPreview').textContent=JSON.stringify(voice,null,2);$('preset').options[0].textContent=voice.name;$('voiceTags').replaceChildren(...[voice.tone,voice.style,'Clear & concise'].map(t=>{const el=document.createElement('span');el.textContent=t;return el}));$('voiceQuote').textContent='“'+voice.guidelines+'”';$('voiceLabel').textContent=voice.name}
$('saveVoice').onclick=()=>{const next={version:1,name:$('voiceName').value.trim()||'My everyday voice',tone:$('warmth').value,style:$('formality').value,guidelines:$('guidelines').value.trim(),avoid:$('avoid').value.split(',').map(x=>x.trim()).filter(Boolean),signature:$('signature').value,sender:$('sender').value};if(persist('replyStudio.voice',next)){voice=next;syncVoice();toast('Your voice profile is saved.')}};
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('exportVoice').onclick=()=>download(voice,'reply-studio-voice.json');$('exportLibrary').onclick=()=>download(responses,'reply-studio-responses.json');$('importVoice').onclick=()=>$('configFile').click();$('configFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error();const data=JSON.parse(await file.text());if(typeof data.name!=='string'||!['Warm','Neutral','Direct'].includes(data.tone)||!['Professional','Casual','Formal'].includes(data.style)||typeof data.guidelines!=='string'||!Array.isArray(data.avoid)||data.avoid.some(x=>typeof x!=='string')||typeof data.signature!=='string'||typeof data.sender!=='string')throw Error();const next={version:1,name:data.name,tone:data.tone,style:data.style,guidelines:data.guidelines,avoid:data.avoid,signature:data.signature,sender:data.sender};if(persist('replyStudio.voice',next)){voice=next;syncVoice();toast('Voice configuration imported.')}}catch{toast('Choose a valid Reply Studio voice configuration JSON file.')}e.target.value=''};
syncVoice();updateCounts();
